/// <summary>
/// <c>METMarkupTransFormEventHandler</c> class holds the EventHandler of the form MarkupTrans
/// </summary>
internal final class METMarkupTransFormEventHandler
{
}

Method.Source:
/// <summary>
/// EventHandler for formControlStr MarkupTrans_METAdvancedCalculation
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormControlEventHandler(formControlStr(MarkupTrans, MarkupTrans_METChargesMethod), FormControlEventType::Modified)]
public static void MarkupTrans_METChargesMethod_OnModified(FormControl sender, FormControlEventArgs e)
{
    FormRun             formRun         = sender.formRun();
    FormDataSource      markupTrans_DS  = formRun.dataSource(formDataSourceStr(MarkupTrans, MarkupTrans));
    MarkupTrans         markupTransloc  = markupTrans_DS.cursor();

    if(markupTransloc.MarkupCode == '' || (markupTransloc.MarkupCode != '' && !markupTransloc.METAdvancedCalculation))
    {
        markupTransloc.METChargesMethod = METChargesMethod::None;
        markupTrans_DS.object(fieldNum(MarkupTrans, METChargesMethod)).enabled(false);
    }
    else
    {
        markupTrans_DS.object(fieldNum(MarkupTrans, METChargesMethod)).enabled(true);
    }
}

